public int getCoutMediumClaimByClaimCriteriaNew(ClaimCriteria claimCriteria, int iClinicID) {
	String sQry = "select count(*) from MediumClaim mc where mc.C_ID = "+iClinicID;
	if(claimCriteria.getiPatient_Id() != 0) {
		sQry = sQry + " and mc.P_ID = "+claimCriteria.getiPatient_Id();
	}
	return getHibernateTemplate().find(sQry).get(0);
}

